/**
 * The generated types, and the gate that keeps them honest.
 *
 * ## What is under test
 *
 * `src/lib/api/types.generated.ts` is generated from the crawler's OpenAPI
 * document and committed. A committed generated file is worth nothing unless
 * something checks it, so this file is that something: it regenerates the
 * file and fails when the result differs from what is committed.
 *
 * ## The failure the gate catches
 *
 * "The contract changed and nobody regenerated the types." It is silent by
 * nature: the compiler is perfectly happy — the types are still types — and
 * the site keeps talking to a contract it no longer knows, right up to the
 * moment a field is read that is no longer there. So the gate has to fail
 * loudly, and the tests below also attack the gate itself: a check that
 * cannot fail proves nothing.
 *
 * ## The crawler's repository is never touched
 *
 * The drift is proved on a *copy* of the contract document, in a temporary
 * directory, through `CONTRACT_OPENAPI_PATH`. The crawler owns that document,
 * and this repository does not get to edit it — not even to prove that the
 * gate works.
 */

import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { afterAll, describe, expect, it } from 'vitest';
import { parse } from 'yaml';
import {
  CONTRACT_DOCUMENT_SHA256,
  PRODUCT_CARD_FIELDS,
  PRODUCT_DETAIL_FIELDS,
  TARGET_SUMMARY_FIELDS,
} from '@/lib/api/types.generated';
import { loadContractDocument } from './global-setup';

/** The root of this repository. */
const ROOT = resolve(__dirname, '..');

/** The generator, as it is run from the command line. */
const GENERATOR = resolve(ROOT, 'scripts', 'generate-contract-types.mjs');

/** The temporary directories this file created, removed when it is done. */
const temporary: string[] = [];

/** What one run of the generator said. */
interface Run {
  /** The exit code: 0 when the generator was satisfied. */
  status: number;
  /** Everything the generator wrote, on either stream. */
  output: string;
}

/**
 * Run the generator and report what it said.
 *
 * The generator is run as a process, not imported, because the gate is the
 * command: a check that only exists as a function nobody runs is not a gate.
 */
function runGenerator(args: string[], env: Record<string, string> = {}): Run {
  try {
    const stdout = execFileSync('node', [GENERATOR, ...args], {
      cwd: ROOT,
      env: { ...process.env, ...env },
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return { status: 0, output: stdout };
  } catch (err) {
    const failure = err as { status?: number; stdout?: string; stderr?: string };
    return {
      status: failure.status ?? 1,
      output: `${failure.stdout ?? ''}${failure.stderr ?? ''}`,
    };
  }
}

/**
 * A copy of the contract document with a change in it.
 *
 * The copy is what makes the drift provable without touching the crawler: the
 * generator is pointed at the copy through `CONTRACT_OPENAPI_PATH`, and the
 * gate is asked whether the committed types still describe it.
 */
function modifiedDocument(change: (text: string) => string): string {
  const dir = mkdtempSync(join(tmpdir(), 'product-catalog-contract-types-'));
  temporary.push(dir);

  const path = join(dir, 'catalog-v1.openapi.yaml');
  writeFileSync(path, change(loadContractDocument()), 'utf8');
  return path;
}

afterAll(() => {
  for (const dir of temporary) rmSync(dir, { recursive: true, force: true });
});

/** The properties a contract schema declares, as the site mirrors them. */
function contractFields(schema: unknown): { name: string; type: string; nullable: boolean }[] {
  const properties = (schema as { properties?: Record<string, { type?: unknown }> }).properties ?? {};
  return Object.entries(properties).map(([name, property]) => {
    const declared = property.type;
    const types = Array.isArray(declared) ? declared : [declared];
    return {
      name,
      type: String(types.find((type) => type !== 'null') ?? 'string'),
      nullable: types.includes('null'),
    };
  });
}

describe('the committed types are the ones the contract describes', () => {
  it('are what the generator produces', () => {
    // The staleness gate itself. The contract document lives in another
    // repository and changes there; this is what notices.
    const result = runGenerator(['--check']);
    expect(result.status, result.output).toBe(0);
  });

  it('are regenerated byte for byte', () => {
    // A generator that produced a different file on every run would make the
    // gate above meaningless: it would always fail, and people would stop
    // reading it.
    const first = join(mkdtempSync(join(tmpdir(), 'product-catalog-contract-types-')), 'types.ts');
    const second = join(mkdtempSync(join(tmpdir(), 'product-catalog-contract-types-')), 'types.ts');
    temporary.push(resolve(first, '..'), resolve(second, '..'));

    expect(runGenerator(['--out', first]).status).toBe(0);
    expect(runGenerator(['--out', second]).status).toBe(0);

    expect(readFileSync(first, 'utf8')).toBe(readFileSync(second, 'utf8'));
  });

  it('carry the fingerprint of the document they were generated from', () => {
    // The hash is of the document's bytes, so it notices a change to a
    // comment as well as a change to a schema.
    const fingerprint = createHash('sha256').update(loadContractDocument(), 'utf8').digest('hex');
    expect(CONTRACT_DOCUMENT_SHA256).toBe(fingerprint);
  });

  it('describe the document’s schemas field for field', () => {
    const document = parse(loadContractDocument()) as {
      components: {
        schemas: Record<
          string,
          {
            properties?: Record<string, unknown>;
            allOf?: Array<{ $ref?: string; properties?: Record<string, unknown> }>;
          }
        >;
      };
    };

    const card = contractFields(document.components.schemas.ProductCard);
    expect(card.map((field) => field.name)).toEqual(PRODUCT_CARD_FIELDS.map((f) => f.name));
    for (const field of card) {
      const mirror = PRODUCT_CARD_FIELDS.find((f) => f.name === field.name)!;
      expect(field.type, `${field.name} has another type in the contract`).toBe(mirror.type);
      expect(field.nullable, `${field.name} has another nullability in the contract`).toBe(
        mirror.nullable,
      );
    }

    const target = contractFields(document.components.schemas.TargetSummary);
    expect(target.map((field) => field.name)).toEqual(TARGET_SUMMARY_FIELDS.map((f) => f.name));

    // The detail is the card plus what the detail adds — the same list,
    // extended. What the detail adds is read from the document: a list
    // written here is a list that goes stale when the contract grows a field,
    // and the site then keeps validating answers against a description of the
    // contract that no longer holds.
    const own = (document.components.schemas.ProductDetail?.allOf ?? []).flatMap((part) =>
      Object.keys(part.properties ?? {}),
    );
    expect(own).toContain('history');
    expect(PRODUCT_DETAIL_FIELDS.map((f) => f.name)).toEqual([
      ...PRODUCT_CARD_FIELDS.map((f) => f.name),
      ...own,
    ]);
  });
});

describe('the gate fails when the contract and the types disagree', () => {
  it('fails on a change to the document that changes nothing but its bytes', () => {
    // A comment is part of the contract: the wording of a promise is the
    // promise. A gate that only noticed schema changes would let the wording
    // drift away from the types silently.
    const copy = modifiedDocument((text) => `# a change that means nothing but changes the bytes\n${text}`);

    const result = runGenerator(['--check'], { CONTRACT_OPENAPI_PATH: copy });
    expect(result.status, result.output).not.toBe(0);
    expect(result.output).toContain('OUT OF DATE');
  });

  it('fails on a renamed field', () => {
    const copy = modifiedDocument((text) => text.replace('inStock:', 'inStockFlag:'));

    const result = runGenerator(['--check'], { CONTRACT_OPENAPI_PATH: copy });
    expect(result.status, result.output).not.toBe(0);
    expect(result.output).toContain('OUT OF DATE');
  });

  it('says how to fix it', () => {
    // A gate that fails without saying what to do is a gate people work
    // around.
    const copy = modifiedDocument((text) => `${text}\n# one more line\n`);

    const result = runGenerator(['--check'], { CONTRACT_OPENAPI_PATH: copy });
    expect(result.status, result.output).not.toBe(0);
    expect(result.output).toContain('npm run contract-types');
  });
});
